questionvariables.text:
perfect_squares: [1,4,9,16,25,36,49,64,81,100];

n1: rand(10)+1;
n2: (rand(8)+1)/(rand(6)+10);

n3_base: (rand(5)+2)^2;
n3: block([simp: false], sqrt(n3_base)^2)

n4_base: rand(20)+2;
while member(n4_base, perfect_squares) do n4_base: rand(20)+2;
n4: block([simp: false], sqrt(n4_base))

n5_base: rand(20)+2;
while member(n5_base, perfect_squares) or n5_base = n4_base do n5_base: rand(20)+2;
n5: block([simp: false], sqrt(n5_base))

n6: %pi;

allpairs: [
  [n1, false], [n2, false], [n3, false],
  [n4, true],  [n5, true],  [n6, true]
]

shuffle_list(lst) := block(
  [n: length(lst), l: lst, i, j, tmp],
  for i: n thru 2 step -1 do (
    j: rand(i)+1,
    tmp: l[i], l[i]: l[j], l[j]: tmp
  ),
  l
)

ta1: shuffle_list(allpairs)

/* separate variable purely for grading */
correctvals: map(lambda([p], p[1]), sublist(allpairs, lambda([p], p[2])))
